<?php require_once __DIR__.'/../config/db.php'; require_once __DIR__.'/../services/authService.php'; require_once __DIR__.'/../includes/csrf.php'; if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST required');} requireValidCsrf(); try{registerAccount(openDatabase(),$_POST);header('Location: register.php?created=1',true,303);exit;}catch(InvalidArgumentException $e){http_response_code(422);$message=$e->getMessage();}catch(PDOException $e){$message='An account with that email may already exist.';http_response_code(422);}catch(Throwable $e){error_log($e->getMessage());http_response_code(500);$message='Unable to create account.';} require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Account was not created</h1><div class="alert alert-danger"><?=htmlspecialchars($message,ENT_QUOTES,'UTF-8')?></div><a class="btn btn-secondary" href="register.php">Return to registration</a></main><?php require __DIR__.'/../includes/footer.php'; ?>
